-- 0021_bpej_cislenik.sql — globálny číselník BPEJ→skupina (Príloha č.3 z.220/2004, 7138 kódov)
-- + sadzby odvodov NV 58/2013 (trvalé + dočasné €/m²); backfill bpej_zones a parcels.
CREATE TABLE IF NOT EXISTS bpej_cislenik (code TEXT PRIMARY KEY, skupina INTEGER NOT NULL);
ALTER TABLE bpej_cennik ADD COLUMN eur_m2_docasne REAL;
DELETE FROM bpej_cennik;
DELETE FROM bpej_cislenik;
UPDATE bpej_zones SET skupina=(SELECT c.skupina FROM bpej_cislenik c WHERE c.code=bpej_zones.code) WHERE code IS NOT NULL;
UPDATE parcels SET bpej_skupina=(SELECT c.skupina FROM bpej_cislenik c WHERE c.code=parcels.bpej) WHERE bpej IS NOT NULL;
UPDATE parcels SET odnatie_eur=(SELECT k.eur_m2 FROM bpej_cennik k WHERE k.skupina=parcels.bpej_skupina) WHERE bpej_skupina IS NOT NULL;
